#!/bin/bash
# Task 128-w4-form1 -- meshsim sim/ WORKER4 (branch sim-w4 25b6e93). TIMING TASK: keep the box quiet while it runs.
# Threads, form 1: independent chips on independent threads (D13 pinned, D18 clang release):
#   0. build; test_parallel (clang debug); footprint per chip from Sizes (mesh, synth);
#   1. one chip per thread: P-cores 1..6 one per core (CPUs 0,2,..), 12 with hyperthreads (0-11); E-cores 1 and 4; 3 repeats;
#   2. sixteen chips per thread: P1, P6, P12, E4; 3 repeats;
#   3. the same 12 chips on 1, 6, 12 threads: identical digests (VERDICT), perf stat.
# Chips: the framework mesh (W6's busy 8x8 at rate 0.35, Routers on Links of 3) and the synthetic chip (64 nodes, every kind).
# Expected ~5 min.
# From an embedded kit (sim/ at 25b6e93: Makefile, src, bench/threads, the thread tests). Writes only results/128-w4-form1/.
# Scratch in /tmp, removed first and at the end. Safe to re-run.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/128-w4-form1; mkdir -p "$RES"; rm -f "$RES/raw.txt"
W=/tmp/w4-128-w4-form1; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "2d826957834b0b452d28484aa113e638863a97d0e8463ccd3e3c81f854b9eb34" ] || { echo "kit sha256 mismatch (want 2d826957834b0b452d28484aa113e638863a97d0e8463ccd3e3c81f854b9eb34)"; exit 2; }
mkdir -p "$W/kit" && tar -xzf "$W/kit.tgz" -C "$W/kit" || exit 2
S=$W/kit/sim
FAILS=0; FAIL=0
sec() { echo; echo "==== $*  [$(date +%T)]"; }
verdict() { echo "VERDICT $1: $2"; [ "$2" = PASS ] || FAIL=1; }
START=$(date +%s)
{
sec "machine"; uname -r; nproc; lscpu | grep -E 'Model name|^CPU\(s\)'; uptime; clang++ --version | head -1
# Shared by W4's task bodies. run TAG CPUSET cmd...: one run under taskset (and perf stat when PERF=1); appends
# "TAG <bench line> [perf: ...]" to $RES/raw.txt.
run() {
  local tag=$1 cpus=$2; shift 2
  if [ "${PERF:-0}" = 1 ]; then
    taskset -c "$cpus" perf stat -x, -e cycles,instructions,cache-misses -o "$W/perf.csv" -- "$@" > "$W/out.txt" 2> "$W/err.txt"
  else
    taskset -c "$cpus" "$@" > "$W/out.txt" 2> "$W/err.txt"
  fi
  local rc=$?
  local line; line=$(grep -E '^threads ' "$W/out.txt" | tail -1)
  if [ $rc -ne 0 ] || [ -z "$line" ]; then echo "RUNFAIL $tag rc=$rc: $*"; head -5 "$W/err.txt"; FAILS=$((FAILS + 1)); return 1; fi
  local pc=""
  [ "${PERF:-0}" = 1 ] && pc=" perf: $(awk -F, '$3 ~ /cycles/ && $3 !~ /ref/ { split($3,a,"/"); k=(a[1]=="cpu_atom")?"atom":"core"; c[k]+=$1 }
      $3 ~ /instructions/ { split($3,a,"/"); k=(a[1]=="cpu_atom")?"atom":"core"; i[k]+=$1 }
      $3 ~ /cache-misses/ { split($3,a,"/"); k=(a[1]=="cpu_atom")?"atom":"core"; m[k]+=$1 }
      END { printf "core_cycles=%s core_instr=%s core_cmiss=%s atom_cycles=%s atom_instr=%s", c["core"], i["core"], m["core"], c["atom"], i["atom"] }' "$W/perf.csv")"
  echo "$tag $line$pc" | tee -a "$RES/raw.txt"
}
field() { grep -o "$1=[^ ]*" | cut -d= -f2; }
# Task body: form 1, independent chips on independent threads (WORKER4). Sourced by the task (mk_task.sh).
cd "$S" || exit 2
sec "build (clang release, D18) and the thread tests (clang debug: ASan, UBSan)"
make -j8 CC_NAME=clang MODE=release build/clang-release/bench_threads > "$RES/build.log" 2>&1 || { tail -20 "$RES/build.log"; verdict build FAIL; exit 1; }
make -j8 CC_NAME=clang MODE=debug build/clang-debug/test_parallel >> "$RES/build.log" 2>&1 && ./build/clang-debug/test_parallel \
  && verdict "test_parallel (debug)" PASS || verdict "test_parallel (debug)" FAIL
B=build/clang-release/bench_threads

sec "footprint per chip (D15), from Sizes"
for c in mesh synth; do $B --sizes --chip $c | tee -a "$RES/sizes.txt"; done

sec "1. one chip per thread (as W6's N1): P-cores one per core 1..6, then 12 with hyperthreads; E-cores 1 and 4; 3 repeats"
for rep in 1 2 3; do for c in mesh synth; do
  V="--chip $c --cycles 40000 --warmup 4000"
  for n in 1 2 3 4 5 6; do
    cpus=$(seq -s, 0 2 $((2 * n - 2)))
    run "N1-P$n" 0-11 $B $V --chips $n --threads $n --cpus $cpus
  done
  run "N1-P12" 0-11 $B $V --chips 12 --threads 12 --cpus 0-11
  run "N1-E1" 12-15 $B $V --chips 1 --threads 1 --cpus 12
  run "N1-E4" 12-15 $B $V --chips 4 --threads 4 --cpus 12-15
done; done

sec "2. sixteen chips per thread (past L2, as W6's N16): P1, P6, P12; E4; 3 repeats"
for rep in 1 2 3; do for c in mesh synth; do
  V="--chip $c --cycles 4000 --warmup 400"
  run "N16-P1" 0-11 $B $V --chips 16 --threads 1 --cpus 0
  run "N16-P6" 0-11 $B $V --chips 96 --threads 6 --cpus 0,2,4,6,8,10
  run "N16-P12" 0-11 $B $V --chips 192 --threads 12 --cpus 0-11
  run "N16-E4" 12-15 $B $V --chips 64 --threads 4 --cpus 12-15
done; done

sec "3. the same 12 chips on 1, 6 and 12 threads: identical digests (and IPC, perf stat)"
for c in mesh synth; do
  V="--chip $c --chips 12 --cycles 10000 --warmup 1000"
  PERF=1 run "D-P1" 0-11 $B $V --threads 1 --cpus 0
  PERF=1 run "D-P6" 0-11 $B $V --threads 6 --cpus 0,2,4,6,8,10
  PERF=1 run "D-P12" 0-11 $B $V --threads 12 --cpus 0-11
  n=$(grep "^D-P" "$RES/raw.txt" | grep "chip=$c " | field digest | sort -u | wc -l)
  [ "$n" = 1 ] && verdict "digests of 12 $c chips on 1, 6, 12 threads" PASS || verdict "digests of 12 $c chips ($n distinct)" FAIL
done
[ "$FAILS" = 0 ] && verdict "every run completed" PASS || verdict "every run completed ($FAILS failed)" FAIL
sec "done in $(($(date +%s) - START)) s"
} 2>&1 | tee "$RES/run.log"
grep '^VERDICT' "$RES/run.log" > "$RES/VERDICTS.txt"
rm -rf "$W"
grep -q ': FAIL$' "$RES/VERDICTS.txt" && exit 1
exit 0
